-- ============================================================================
--  SuperStore ERD Database
--  Sumber data : SampleSuperstore.csv (9994 baris transaksi)
--  DBMS        : MySQL 8.x / MariaDB 10.4+
--  Cara import : mysql -u root -p < SuperStore_ERD.sql
--  PERINGATAN  : file ini menghapus tabel lama di database superstore_db.
-- ============================================================================
--
--  ERD (Mermaid):
--  erDiagram
--      REGIONS ||--o{ LOCATIONS : contains
--      LOCATIONS ||--o{ FACT_SALES : located_at
--      SHIP_MODES ||--o{ FACT_SALES : shipped_by
--      SEGMENTS ||--o{ FACT_SALES : belongs_to
--      CATEGORIES ||--o{ SUBCATEGORIES : has
--      SUBCATEGORIES ||--o{ FACT_SALES : classified_as
--
--  Normalisasi: Region, ship mode, segment, kategori, sub-kategori, dan
--  lokasi dipisah menjadi tabel dimensi. Country tetap di LOCATIONS karena
--  dataset hanya berisi satu negara (United States).
--
--  Grain FACT_SALES = 1 baris item transaksi SuperStore.
--  Karena dataset tidak memiliki Order ID / Customer ID, dibuat surrogate key
--  SALE_ID. Jika nanti tersedia data order/customer, tambahkan tabel ORDERS
--  dan CUSTOMERS lalu hubungkan ke FACT_SALES.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS db_superstore
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE db_superstore;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP VIEW IF EXISTS v_sales_detail;
DROP TABLE IF EXISTS fact_sales;
DROP TABLE IF EXISTS locations;
DROP TABLE IF EXISTS subcategories;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS ship_modes;
DROP TABLE IF EXISTS segments;
DROP TABLE IF EXISTS regions;
SET FOREIGN_KEY_CHECKS = 1;

-- ----------------------------------------------------------------------------
-- 1. Tabel dimensi
-- ----------------------------------------------------------------------------

CREATE TABLE regions (
  region_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  region_name VARCHAR(50)  NOT NULL,
  PRIMARY KEY (region_id),
  UNIQUE KEY uq_regions_name (region_name)
) ENGINE=InnoDB;

CREATE TABLE ship_modes (
  ship_mode_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  ship_mode_name VARCHAR(50)  NOT NULL,
  PRIMARY KEY (ship_mode_id),
  UNIQUE KEY uq_ship_modes_name (ship_mode_name)
) ENGINE=InnoDB;

CREATE TABLE segments (
  segment_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  segment_name VARCHAR(50)  NOT NULL,
  PRIMARY KEY (segment_id),
  UNIQUE KEY uq_segments_name (segment_name)
) ENGINE=InnoDB;

CREATE TABLE categories (
  category_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_name VARCHAR(100) NOT NULL,
  PRIMARY KEY (category_id),
  UNIQUE KEY uq_categories_name (category_name)
) ENGINE=InnoDB;

CREATE TABLE subcategories (
  subcategory_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  subcategory_name VARCHAR(100) NOT NULL,
  category_id      INT UNSIGNED NOT NULL,
  PRIMARY KEY (subcategory_id),
  UNIQUE KEY uq_subcategories_name (subcategory_name),
  KEY idx_subcategories_category (category_id),
  CONSTRAINT fk_subcategories_category
    FOREIGN KEY (category_id) REFERENCES categories (category_id)
    ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE locations (
  location_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  country     VARCHAR(100) NOT NULL,
  state       VARCHAR(100) NOT NULL,
  city        VARCHAR(100) NOT NULL,
  postal_code VARCHAR(20)  NOT NULL,
  region_id   INT UNSIGNED NOT NULL,
  PRIMARY KEY (location_id),
  UNIQUE KEY uq_locations (country, state, city, postal_code, region_id),
  KEY idx_locations_state (state),
  KEY idx_locations_region (region_id),
  CONSTRAINT fk_locations_region
    FOREIGN KEY (region_id) REFERENCES regions (region_id)
    ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

-- ----------------------------------------------------------------------------
-- 2. Tabel fakta
-- ----------------------------------------------------------------------------

CREATE TABLE fact_sales (
  sale_id        BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  ship_mode_id   INT UNSIGNED NOT NULL,
  segment_id     INT UNSIGNED NOT NULL,
  location_id    INT UNSIGNED NOT NULL,
  subcategory_id INT UNSIGNED NOT NULL,
  sales          DECIMAL(12,4) NOT NULL DEFAULT 0.0000,
  quantity       INT UNSIGNED  NOT NULL DEFAULT 1,
  discount       DECIMAL(5,4)  NOT NULL DEFAULT 0.0000,
  profit         DECIMAL(12,4) NOT NULL DEFAULT 0.0000,
  PRIMARY KEY (sale_id),
  CONSTRAINT chk_fact_quantity CHECK (quantity > 0),
  CONSTRAINT chk_fact_discount CHECK (discount >= 0 AND discount <= 1),
  KEY idx_fact_ship_mode (ship_mode_id),
  KEY idx_fact_segment (segment_id),
  KEY idx_fact_location (location_id),
  KEY idx_fact_subcategory (subcategory_id),
  CONSTRAINT fk_fact_ship_mode
    FOREIGN KEY (ship_mode_id) REFERENCES ship_modes (ship_mode_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_fact_segment
    FOREIGN KEY (segment_id) REFERENCES segments (segment_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_fact_location
    FOREIGN KEY (location_id) REFERENCES locations (location_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_fact_subcategory
    FOREIGN KEY (subcategory_id) REFERENCES subcategories (subcategory_id)
    ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

-- ----------------------------------------------------------------------------
-- 3. Data dimensi
-- ----------------------------------------------------------------------------

